class Solution {
  private int m, n;

  private boolean horizontalEntry(int r, int a) {
    boolean[] s1 = new boolean[3], s2 = new boolean[3]; // 0 = above/below, 1 = left, 2 = start
    s1[0] = r > 0;
    s1[1] = a > 0;
    s1[2] = r == 0 && a == 0;
    s2[0] = r < m - 1;
    s2[1] = a > 0;
    s2[2] = r == m - 1 && a == 0;
    for (int e1 = 0; e1 < 3; e1++)
      for (int e2 = 0; e2 < 3; e2++) if (s1[e1] && s2[e2] && !(e1 == 1 && e2 == 1)) return true;
    return false;
  }

  private boolean horizontalExit(int r, int b) {
    boolean[] t1 = new boolean[3], t2 = new boolean[3]; // 0 = down/up, 1 = right, 2 = end
    t1[0] = r < m - 1;
    t1[1] = b < n - 1;
    t1[2] = r == m - 1 && b == n - 1;
    t2[0] = r > 0;
    t2[1] = b < n - 1;
    t2[2] = r == 0 && b == n - 1;
    for (int x1 = 0; x1 < 3; x1++)
      for (int x2 = 0; x2 < 3; x2++) if (t1[x1] && t2[x2] && !(x1 == 1 && x2 == 1)) return true;
    return false;
  }

  private boolean singleCell(int r, int c) {
    // entries: p1 in {above(0), left(1), start(2)}, p2 in {below(0), left(1), start(2)}
    // exits: p1 in {down(0), right(1), end(2)}, p2 in {up(0), right(1), end(2)}
    boolean[] e1s = {r > 0, c > 0, r == 0 && c == 0},
        e2s = {r < m - 1, c > 0, r == m - 1 && c == 0};
    boolean[] x1s = {r < m - 1, c < n - 1, r == m - 1 && c == n - 1},
        x2s = {r > 0, c < n - 1, r == 0 && c == n - 1};
    for (int e1 = 0; e1 < 3; e1++)
      for (int e2 = 0; e2 < 3; e2++) {
        if (!e1s[e1] || !e2s[e2] || (e1 == 1 && e2 == 1)) continue;
        for (int x1 = 0; x1 < 3; x1++)
          for (int x2 = 0; x2 < 3; x2++) {
            if (!x1s[x1] || !x2s[x2] || (x1 == 1 && x2 == 1)) continue;
            if (e1 == 0 && x2 == 0) continue; // p1 comes from above, p2 leaves upwards
            if (x1 == 0 && e2 == 0) continue; // p1 leaves downwards, p2 arrives from below
            return true;
          }
      }
    return false;
  }

  private boolean verticalTop(int r1, int c) {
    boolean[] e1s = {r1 > 0, c > 0, r1 == 0 && c == 0}; // above, left, start
    boolean[] x2s = {r1 > 0, c < n - 1, r1 == 0 && c == n - 1}; // up, right, end
    for (int e1 = 0; e1 < 3; e1++)
      for (int x2 = 0; x2 < 3; x2++) if (e1s[e1] && x2s[x2] && !(e1 == 0 && x2 == 0)) return true;
    return false;
  }

  private boolean verticalBottom(int r2, int c) {
    boolean[] x1s = {r2 < m - 1, c < n - 1, r2 == m - 1 && c == n - 1}; // down, right, end
    boolean[] e2s = {r2 < m - 1, c > 0, r2 == m - 1 && c == 0}; // below, left, start
    for (int x1 = 0; x1 < 3; x1++)
      for (int e2 = 0; e2 < 3; e2++) if (x1s[x1] && e2s[e2] && !(x1 == 0 && e2 == 0)) return true;
    return false;
  }

  public int maxScore(int[][] grid) {
    m = grid.length;
    n = grid[0].length;
    long best = Long.MIN_VALUE;
    for (int r = 0; r < m; r++) {
      for (int c = 0; c < n; c++) if (singleCell(r, c)) best = Math.max(best, grid[r][c]);
      long[] pre = new long[n + 1];
      for (int c = 0; c < n; c++) pre[c + 1] = pre[c] + grid[r][c];
      long minPrefix = Long.MAX_VALUE;
      for (int b = 1; b < n; b++) {
        int a = b - 1;
        if (horizontalEntry(r, a)) minPrefix = Math.min(minPrefix, pre[a]);
        if (minPrefix != Long.MAX_VALUE && horizontalExit(r, b))
          best = Math.max(best, pre[b + 1] - minPrefix);
      }
    }
    for (int c = 0; c < n; c++) {
      long[] pre = new long[m + 1];
      for (int r = 0; r < m; r++) pre[r + 1] = pre[r] + grid[r][c];
      long minPrefix = Long.MAX_VALUE;
      for (int r2 = 1; r2 < m; r2++) {
        int r1 = r2 - 1;
        if (verticalTop(r1, c)) minPrefix = Math.min(minPrefix, pre[r1]);
        if (minPrefix != Long.MAX_VALUE && verticalBottom(r2, c))
          best = Math.max(best, pre[r2 + 1] - minPrefix);
      }
    }
    return (int) best;
  }
}
